package dev.hrutvik.billing.invoice;
import dev.hrutvik.billing.rating.SubscriptionPlan; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Repository
public class InvoiceStore {
 private final JdbcTemplate jdbc; public InvoiceStore(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public SubscriptionPlan lockSubscription(String tenantId,UUID id){return jdbc.query("""SELECT s.id,s.plan_id,p.currency FROM subscriptions s JOIN billing_plans p ON p.id=s.plan_id AND p.tenant_id=s.tenant_id WHERE s.id=? AND s.tenant_id=? AND s.status='ACTIVE' FOR UPDATE OF s""",(rs,n)->new SubscriptionPlan(rs.getObject("id",UUID.class),rs.getObject("plan_id",UUID.class),rs.getString("currency")),id,tenantId).stream().findFirst().orElseThrow(()->new IllegalArgumentException("active subscription not found"));}
 public Optional<InvoiceResponse> existing(String tenantId,UUID subscriptionId,Instant from,Instant to){return jdbc.query("""SELECT id,invoice_number,currency,total,status FROM invoices WHERE tenant_id=? AND subscription_id=? AND period_start=? AND period_end=?""",(rs,n)->new InvoiceResponse(rs.getObject("id",UUID.class),rs.getString("invoice_number"),subscriptionId,rs.getString("currency"),from,to,rs.getBigDecimal("total"),rs.getString("status"),List.of(),true),tenantId,subscriptionId,from,to).stream().findFirst().map(i->new InvoiceResponse(i.invoiceId(),i.invoiceNumber(),i.subscriptionId(),i.currency(),i.periodStart(),i.periodEnd(),i.total(),i.status(),lines(i.invoiceId()),true));}
 public void insertInvoice(UUID id,String number,String tenantId,UUID subscriptionId,String currency,Instant from,Instant to,BigDecimal total,Instant now){jdbc.update("""INSERT INTO invoices(id,invoice_number,tenant_id,subscription_id,currency,period_start,period_end,total,status,finalized_at,created_at) VALUES(?,?,?,?,?,?,?,?, 'FINALIZED',?,?)""",id,number,tenantId,subscriptionId,currency,from,to,total,now,now);}
 public void insertLine(UUID id,UUID invoiceId,String meterKey,BigDecimal quantity,BigDecimal amount,String snapshot){jdbc.update("""INSERT INTO invoice_lines(id,invoice_id,meter_key,quantity,amount,pricing_snapshot) VALUES(?,?,?,?,?,?::jsonb)""",id,invoiceId,meterKey,quantity,amount,snapshot);}
 private List<InvoiceLineView> lines(UUID invoiceId){return jdbc.query("""SELECT meter_key,quantity,amount FROM invoice_lines WHERE invoice_id=? ORDER BY meter_key""",(rs,n)->new InvoiceLineView(rs.getString("meter_key"),rs.getBigDecimal("quantity"),rs.getBigDecimal("amount")),invoiceId);}
}
